// Custom hook for toggling boolean state
function useToggle(initialValue = false) {
  const [value, setValue] = useState(initialValue);

  const toggle = () => setValue(v => !v);

  // Return both the value and the toggle function
  return [value, toggle];
}

// Usage in a component
function MyComponent() {
  const [isOn, toggleIsOn] = useToggle(false);

  return (
    <>
      <p>Switch is {isOn ? 'ON' : 'OFF'}</p>
      <button onClick={toggleIsOn}>Toggle</button>
    </>
  );
}

// ❌ WRONG - hooks in conditions
function Bad({ showCount }) {
  if (showCount) {
    const [count, setCount] = useState(0); // Order changes!
  }
  const [name, setName] = useState(''); // Sometimes slot 1, sometimes slot 2
}

// ✅ CORRECT - hooks at top level
function Good({ showCount }) {
  const [count, setCount] = useState(0); // Always slot 1
  const [name, setName] = useState(''); // Always slot 2

  if (showCount) {
    // Use the state conditionally, not define it conditionally
    return <div>{count}</div>;
  }
}

// ❌ WRONG - hook in loop
function Bad({ items }) {
  items.forEach(item => {
    const [value, setValue] = useState(item); // Different number of calls each render!
  });
}

// ✅ CORRECT - one useState for all items
function Good({ items }) {
  const [values, setValues] = useState(items);
}

// Simple hook - one purpose
function useOnline() {
  const [online, setOnline] = useState(navigator.onLine);

  useEffect(() => {
    const handleOnline = () => setOnline(true);
    const handleOffline = () => setOffline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  return online;
}

// Composed hook - uses multiple hooks
function useOnlineStatus() {
  const online = useOnline(); // Uses custom hook
  const [lastOnline, setLastOnline] = useState(Date.now());

  useEffect(() => {
    if (online) {
      setLastOnline(Date.now());
    }
  }, [online]);

  return { online, lastOnline };
}

